import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BigNumber, ChartHeader, DataStateHandler } from 'components';
import { useMediaQuery } from 'hooks';

import type { TotalPhiCardData } from '../../types';
import { StyledTotalPhiCard } from './TotalPhiCard.styles';

export interface TotalPhiCardProps {
  data?: TotalPhiCardData;
  loading?: boolean;
  error?: Error | null;
  dataTestId?: string;
}

export const TotalPhiCard: React.FC<TotalPhiCardProps> = ({
  data,
  loading = false,
  error = null,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const isDesktopLarge = useMediaQuery('(min-width: 1440px)');
  const isEmpty = !data || data.bigNumberData.length === 0;

  const chartHeaderConfig = useMemo(
    () => ({
      inline: 'horizontal' as const,
      type: (isDesktopLarge ? 'large' : 'small') as 'large' | 'small',
      alignment: 'left' as const,
    }),
    [isDesktopLarge],
  );

  const header = useMemo(
    () => (
      <ChartHeader
        title={data?.title ?? 'PHI'}
        period={data?.period}
        measure={data?.measure}
        config={chartHeaderConfig}
        dataTestId={dataTestId ? `${dataTestId}-header` : undefined}
      />
    ),
    [chartHeaderConfig, data?.measure, data?.period, data?.title, dataTestId],
  );

  return (
    <StyledTotalPhiCard data-testid={dataTestId}>
      <DataStateHandler
        loading={loading}
        error={error}
        empty={isEmpty}
        message={{
          description: formatMessage({
            id: 'Common.dataUnavailable.title',
            defaultMessage: 'Data not available',
          }),
        }}
        skeletonProps={{
          length: 1,
          width: 'fit-content',
          height: '168px',
          borderRadius: 'medium',
        }}
      >
        {data ? (
          <BigNumber
            className="portfolio-health-total-phi-big-number"
            header={header}
            data={data.bigNumberData}
            asCard
            size="medium"
            spacing="cozy"
            orientation="vertical"
            alignment="left"
            enableTruncation
            dataTestId={dataTestId ? `${dataTestId}-big-number` : undefined}
          />
        ) : null}
      </DataStateHandler>
    </StyledTotalPhiCard>
  );
};
